package com.mamtrex.hospital.auth; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; @Component public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserAccountRepository repo; public JwtFilter(JwtService j,UserAccountRepository r){jwt=j;repo=r;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){try{String u=jwt.subject(h.substring(7));repo.findByUsername(u).ifPresent(x->{var a=x.getRoles().stream().map(r->new SimpleGrantedAuthority("ROLE_"+r.name())).toList();SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,a));});}catch(Exception ignored){}} chain.doFilter(req,res);} }
